const source = $('Execute Workflow Trigger').item.json || {};

const payload = source.payload || {};
const message =
  source.message ||
  payload.message ||
  payload.body?.message ||
  {};

const chatId =
  source.chatId ||
  message.chat?.id ||
  payload.chatId ||
  '';

const raw = String(
  source.rawText ||
  source.text ||
  message.text ||
  payload.text ||
  ''
).trim();

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^["'“”‘’]+|["'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

function parseRenameCommand(rawText) {
  const original = String(rawText || '').trim();
  const normalized = normalize(original);

  const prefixes = [
    'doi ten file',
    'rename file',
    'doi ten tep',
    'doi ten thu muc',
    'rename folder'
  ];

  let bodyOriginal = original;
  let bodyNormalized = normalized;

  for (const prefix of prefixes) {
    if (normalized.startsWith(prefix + ' ')) {
      bodyOriginal = original.slice(prefix.length + 1).trim();
      bodyNormalized = normalized.slice(prefix.length + 1).trim();
      break;
    }

    if (normalized === prefix) {
      return { fileName: '', newName: '' };
    }
  }

  const separators = [
    ' thanh ',
    ' sang ',
    ' doi thanh ',
    ' to ',
    ' into ',
    ' as '
  ];

  for (const sep of separators) {
    const index = bodyNormalized.indexOf(sep);

    if (index !== -1) {
      return {
        fileName: cleanName(bodyOriginal.slice(0, index)),
        newName: cleanName(bodyOriginal.slice(index + sep.length))
      };
    }
  }

  return {
    fileName: cleanName(bodyOriginal),
    newName: ''
  };
}

function preserveExtensionIfNeeded(oldName, newName) {
  const oldExt = String(oldName || '').match(/\.[^\.\s]+$/)?.[0] || '';
  const newExt = String(newName || '').match(/\.[^\.\s]+$/)?.[0] || '';

  if (oldExt && !newExt) {
    return `${newName}${oldExt}`;
  }

  return newName;
}

const parsed = parseRenameCommand(raw);

const fileId =
  source.fileId ||
  source.targetId ||
  payload.fileId ||
  payload.targetId ||
  '';

const fileName = cleanName(
  source.fileName ||
  source.targetName ||
  payload.fileName ||
  payload.targetName ||
  parsed.fileName
);

let newName = cleanName(
  source.newName ||
  payload.newName ||
  parsed.newName
);

newName = preserveExtensionIfNeeded(fileName, newName);

const hasTarget = Boolean((fileId || fileName) && newName);

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    rawText: raw,
    text: normalize(raw),

    fileId,
    targetId: fileId,
    fileName,
    targetName: fileName,
    newName,

    hasTarget,
    response: hasTarget
      ? ''
      : '📄 <b>Đổi tên file</b>\n\nVí dụ:\n<code>đổi tên file test_n8n.md thành test_n9n</code>\n<code>rename file old.txt to new.txt</code>'
  }
}];

const source = $('Prepare Action').item.json || {};

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const rows = $input
  .all()
  .map((item) => item.json || {})
  .filter((item) => item.id || item.name);

if (!rows.length) {
  return [{
    json: {
      ...source,
      found: false,
      fileId: '',
      targetId: '',
      response: 'Không tìm thấy file phù hợp với: <b>' + escapeHtml(source.fileName || source.targetName || '') + '</b>'
    }
  }];
}

const file = rows[0];

return [{
  json: {
    ...source,
    ...file,
    found: true,
    oldName: file.name || source.fileName || source.targetName || '',
    fileId: file.id || source.fileId || '',
    targetId: file.id || source.targetId || source.fileId || '',
    fileName: file.name || source.fileName || source.targetName || '',
    webViewLink: file.webViewLink || source.webViewLink || '',
    webContentLink: file.webContentLink || source.webContentLink || '',
    mimeType: file.mimeType || source.mimeType || '',
    newName: source.newName || ''
  }
}];

const item = $input.item.json || {};
const fileId = item.fileId || item.targetId || item.id || '';

if (!fileId) {
  return [{
    json: {
      ...item,
      response: 'Không có File ID để đổi tên.'
    }
  }];
}

return [{
  json: {
    ...item,
    fileId,
    targetId: fileId
  }
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

function getJson(nodeName) {
  try { return $(nodeName).item.json || {}; } catch (e) { return {}; }
}

const item = $input.item.json || {};
const prepared = getJson('Prepare Action');
const resolved = getJson('Resolve Search Result');
const target = getJson('Prepare Rename Target');

const source = {
  ...prepared,
  ...resolved,
  ...target
};

const oldName = source.oldName || source.fileName || prepared.fileName || 'Không rõ tên cũ';
const newName = item.name || source.newName || 'Không rõ tên mới';
const fileId = item.id || source.fileId || source.targetId || '';
const mimeType = item.mimeType || source.mimeType || '';
const link = item.webViewLink || source.webViewLink || (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

let text = '✅ <b>Đã đổi tên file</b>\n\n';
text += `Tên cũ: <b>${escapeHtml(oldName)}</b>\n`;
text += `Tên mới: <b>${escapeHtml(newName)}</b>\n`;

if (mimeType) {
  text += `Loại: <code>${escapeHtml(mimeType)}</code>\n`;
}

if (fileId) {
  text += `ID: <code>${escapeHtml(fileId)}</code>\n`;
}

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>`;
}

return [{
  json: {
    chatId: source.chatId || item.chatId,
    text: text.trim()
  }
}];
